import { page } from 'vitest/browser'
import { api, type Host, historySchema, hostSchema } from '@/api'
import { forget } from '@/hooks/useLiveSeries'
// The stylesheet is imported for its effect, not its exports: every class under
// measurement here is generated by Tailwind from this entry point. Without it
// nothing below has a layout worth measuring, and every element fits because
// nothing is styled -- a pass that measures nothing.
import '@/index.css'
import { HostView } from './host'

/**
 * The host page at 390 px, in a real browser (Phase 11, UI-SPEC backstops).
 *
 * jsdom performs no layout, so host.test.tsx can say that a class is present
 * but not that a 63-character hostname wraps instead of widening the page. This
 * file measures exactly two shapes the UI-SPEC left as backstops:
 *
 *   1. an amd64 desktop: container and hardening notices, k10temp twice, an
 *      nvme with limits, an nct6798 with two temperatures and five fans (one
 *      stopped), acpitz, three physical interfaces and twelve virtual ones with
 *      the disclosure open, two filesystem rows;
 *   2. long identifiers: hostname, model, OS, kernel, data-directory path and a
 *      filesystem device, each longer than a phone is wide.
 *
 * The page is rendered in a 390-px box inside a 390-px viewport, so the
 * breakpoints are the phone's. The rule measured is the one the phone suite
 * states for every route: no
 * element ends to the right of the page, except inside an element that scrolls
 * sideways on purpose (the ProcSubset=all code line does).
 */

vi.mock('@/routes/__root', () => ({
  authenticatedRoute: { addChildren: () => undefined },
}))

const PHONE_WIDTH = 390

const read = <T,>(value: T) => ({ readable: true as const, value })
const hidden = (code: string, message: string) => ({
  readable: false as const,
  reason: { code, message },
})

const HARDENING_STAT =
  "Hidden by the unit's ProcSubset=pid: /proc/stat is not visible to holzkube-manager. Set ProcSubset=all in the unit's [Service] section to show it."
const HARDENING_MEMINFO =
  "Hidden by the unit's ProcSubset=pid: /proc/meminfo is not visible to holzkube-manager. Set ProcSubset=all in the unit's [Service] section to show it."

const linkOf = (
  name: string,
  up: boolean,
  speed: number | null,
  rx: number | null,
  tx: number | null,
) => ({
  name,
  up,
  speed_mbit: speed,
  rx_bytes_per_sec: rx,
  tx_bytes_per_sec: tx,
})

const temp = (
  chip: string,
  kind: string,
  label: string,
  celsius: number,
  high: number | null,
  crit: number | null,
) => ({
  chip,
  kind,
  label,
  celsius,
  high_c: high,
  critical_c: crit,
})

const usage = {
  size_bytes: 1_000_204_886_016,
  used_bytes: 412_316_860_416,
  available_bytes: 536_870_912_000,
}

