/** Every identifier the page shows, each longer than a phone is wide. */
function longIdentifiers(): Host {
  // 63 characters with no hyphen: the longest legal label, and one word with no
  // place the browser would break it of its own accord.
  const hostname = 'examplehost'.repeat(6).slice(0, 63)
  const model = 'Supermicro Super Server X13SAE-F-Ultra-Long-Board-Revision-2.00-ABCDEFGHIJ' // 70+
  const os = 'An-Operating-System-Name-With-No-Spaces-In-It-At-All-v123456' // 60
  const kernel = `6.12.47-${'k'.repeat(82)}` // 90
  const path = `/var/lib/holzkube-manager/${'d'.repeat(94)}` // 120
  const deviceName = `/dev/disk/by-id/nvme-Samsung_SSD_990_PRO_2TB_S7KHNJ0W${'x'.repeat(17)}` // 70
  expect(hostname).toHaveLength(63)
  expect(model.length).toBeGreaterThanOrEqual(70)
  expect(os).toHaveLength(60)
  expect(kernel).toHaveLength(90)
  expect(path).toHaveLength(120)
  expect(deviceName).toHaveLength(70)
  return shape({
    device: {
      hostname: read(hostname),
      model: read(model),
      os: read(os),
      kernel: read(kernel),
    },
    service: {
      data_dir: {
        path,
        size: read({ bytes: 432013312, measured_at: '2026-09-28T09:59:40Z' }),
      },
    },
    live: {
      filesystems: [
        {
          mount: '/',
          device: deviceName,
          fstype: 'ext4',
          roles: ['root', 'data directory'],
          usage: read(usage),
        },
      ],
    },
  })
}

function renderAtPhoneWidth(host: Host): HTMLElement {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  const { container } = render(
    <QueryClientProvider client={client}>
      <div data-testid="phone" style={{ width: `${PHONE_WIDTH}px` }}>
        <HostView host={host} stale={null} />
      </div>
    </QueryClientProvider>,
  )
  const phone = container.querySelector<HTMLElement>('[data-testid="phone"]')
  if (phone === null) throw new Error('the 390-px container did not render')
  // Every disclosure open: the virtual interfaces are part of what must fit.
  for (const d of phone.querySelectorAll('details')) d.open = true
  return phone
}

/** True when node sits inside an element (below root) that scrolls sideways by design. */
function scrollsSideways(node: Node, root: Element): boolean {
  for (let a = node.parentElement; a !== null && a !== root; a = a.parentElement) {
    const ox = getComputedStyle(a).overflowX
    if (ox === 'auto' || ox === 'scroll') return true
  }
  return false
}

/**
 * True inside an `sr-only` element: a 1-px box that clips its content, whose
 * text is laid out past it and never drawn. The sensors' "critical" label is one.
 */
function screenReaderOnly(el: Element, root: Element): boolean {
  for (let a: Element | null = el; a !== null && a !== root; a = a.parentElement) {
    const r = a.getBoundingClientRect()
    if (r.width <= 1 && r.height <= 1 && getComputedStyle(a).overflowX === 'hidden') return true
  }
  return false
}

function describeEl(el: Element): string {
  const text = (el.textContent ?? '').replace(/\s+/g, ' ').trim().slice(0, 80)
  return `<${el.tagName.toLowerCase()} class="${el.getAttribute('class') ?? ''}"> "${text}"`
}

/**
 * Every element and every run of text that ends right of the container, with
 * where it ends.
 *
 * Elements alone are not enough, and that was measured: a block that does not
 * wrap keeps its own box at the container's width while its text runs on past
 * it, so a notice set to `whitespace-nowrap` passed an element-only check. The
 * text is therefore measured line by line, through a Range over each text node.
 */
function overflowing(phone: HTMLElement): string[] {
  const edge = phone.getBoundingClientRect().right + 0.5
  const out: string[] = []
  for (const el of phone.querySelectorAll('*')) {
    const r = el.getBoundingClientRect()
    if (r.width === 0 && r.height === 0) continue
    if (r.right <= edge) continue
    if (scrollsSideways(el, phone)) continue
    out.push(`${describeEl(el)} ends at ${r.right.toFixed(1)} > ${edge.toFixed(1)}`)
  }
  const walker = document.createTreeWalker(phone, NodeFilter.SHOW_TEXT)
  const range = document.createRange()
  for (let n = walker.nextNode(); n !== null; n = walker.nextNode()) {
    const parent = n.parentElement
    if (parent === null || scrollsSideways(n, phone) || screenReaderOnly(parent, phone)) continue
    range.selectNodeContents(n)
    const right = Math.max(0, ...[...range.getClientRects()].map((r) => r.right))
    if (right <= edge) continue
    out.push(`text of ${describeEl(parent)} ends at ${right.toFixed(1)} > ${edge.toFixed(1)}`)
  }
  return out
}

// The viewport, not only the container, is 390 px wide: the cards switch their
// label column on at the md breakpoint, and a media query reads the viewport.
// A 390-px box inside the project's 1200-px viewport would measure the desktop
// grid squeezed into a phone's width -- a layout no phone ever renders.
//
// HostView asks for the recorded history (Phase 12). It is answered here with
// an empty one: a real request from this project would fail and draw the
// "No recorded history yet" note, which no page with a daemon behind it shows,
// and the measurement would be of a shape that does not exist.
beforeEach(async () => {
  vi.spyOn(api, 'hostHistory').mockResolvedValue(historySchema.parse({ series: {} }))
  await page.viewport(PHONE_WIDTH, 900)
})

afterEach(async () => {
  cleanup()
  vi.restoreAllMocks()
  forget()
  await page.viewport(1200, 900)
})

describe('/host at 390 px', () => {
  it('fits the amd64 desktop shape: notices, many sensors and fans, twelve virtual interfaces', () => {
    const phone = renderAtPhoneWidth(amd64())
    expect(phone.getBoundingClientRect().width).toBe(PHONE_WIDTH)
    // The shape is what it says it is: both notices, every sensor, every link.
    expect(phone.textContent).toContain('runs in a container')
    expect(phone.textContent).toContain('ProcSubset=all')
    expect(phone.textContent).toContain('AUXTIN0')
    expect(phone.textContent).toContain('fan5')
    expect(phone.textContent).toContain('wg0')
    // The virtual interfaces are laid out, not only present in the DOM: a
    // closed <details> would give them no box and nothing to measure.
    const lastVirtual = [...phone.querySelectorAll('li')].find((li) =>
      li.textContent?.startsWith('wg0'),
    )
    expect(lastVirtual?.getBoundingClientRect().height ?? 0).toBeGreaterThan(0)
    expect(overflowing(phone)).toEqual([])
  })

  it('wraps long identifiers instead of widening the page', () => {
    const host = longIdentifiers()
    const phone = renderAtPhoneWidth(host)
    expect(phone.getBoundingClientRect().width).toBe(PHONE_WIDTH)
    for (const s of [host.device.hostname, host.device.model, host.device.os, host.device.kernel]) {
      if (!s.readable) throw new Error('shape built with an unreadable identifier')
      expect(phone.textContent).toContain(s.value)
    }
    expect(phone.textContent).toContain(host.service.data_dir.path)
    expect(phone.textContent).toContain(host.live.filesystems[0]?.device)
    expect(overflowing(phone)).toEqual([])
  })
})
